import { existsSync, readdirSync } from "node:fs";
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";

import { print } from "./typegen/print.ts";
import type { QuerySource } from "./typegen/print.ts";
import { findQueries } from "./typegen/queries.ts";
import type { QueryModule } from "./typegen/queries.ts";
import { loadStudioSchema } from "./typegen/schema.ts";
import type { SchemaType } from "./typegen/schema.ts";

export interface TypegenResult {
  queries: number;
  errors: string[];
  written: boolean;
}

const HEADER = `// Generated by @visio/sanity from the Studio's schema and the site's
// defineQuery constants. Do not edit; the dev server keeps it current, and
// the build writes it.`;

const SOURCE = /\.tsx?$/v;

function* sourceFiles(dir: string): Generator<string> {
  if (!existsSync(dir)) {
    return;
  }

  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const file = path.join(dir, entry.name);

    if (entry.isDirectory()) {
      if (entry.name !== "node_modules" && !entry.name.startsWith(".")) {
        yield* sourceFiles(file);
      }
    } else if (SOURCE.test(entry.name) && !entry.name.endsWith(".d.ts")) {
      yield file;
    }
  }
}

/** Kept between changes, so a save refinds one file instead of all of them. */
export class Typegen {
  protected schema: SchemaType | undefined;
  private modules = new Map<string, QueryModule>();
  private readonly root: string;
  private readonly studio: string;
  private readonly src: string;
  private readonly out: string;

  constructor(root: string, studio: string) {
    this.root = root;
    this.studio = studio;
    this.src = path.join(root, "src");
    this.out = path.join(root, "sanity.types.d.ts");
  }

  async loadSchema(): Promise<void> {
    this.schema = await loadStudioSchema(this.studio);
  }

  isQueryFile(file: string): boolean {
    return SOURCE.test(file) && file.startsWith(this.src + path.sep);
  }

  scan(): void {
    this.modules.clear();

    for (const file of sourceFiles(this.src)) {
      this.refind(file);
    }
  }

  /** A shared projection changed: the files whose queries were built from it change too. */
  update(file: string): void {
    const dependents = this.modules
      .entries()
      .filter(([, m]) => m.deps.includes(file))
      .map(([f]) => f)
      .toArray();

    this.refind(file);

    for (const dependent of dependents) {
      this.refind(dependent);
    }
  }

  private refind(file: string): void {
    if (!existsSync(file)) {
      this.modules.delete(file);

      return;
    }

    const found = findQueries(this.root, file);

    if (found.queries.length || found.errors.length) {
      this.modules.set(file, found);
    } else {
      this.modules.delete(file);
    }
  }

  async write(): Promise<TypegenResult> {
    if (!this.schema) {
      await this.loadSchema();
    }

    const sources: QuerySource[] = [...this.modules]
      .toSorted(([a], [b]) => a.localeCompare(b))
      .map(([file, m]) => ({
        file: path.relative(this.root, file),
        queries: m.queries,
      }));

    const { schema } = this;

    if (!schema) {
      throw new Error(
        "[@visio/sanity] typegen has no schema after loading it."
      );
    }

    const printed = print(schema, sources, HEADER);

    const previous = existsSync(this.out)
      ? await readFile(this.out, "utf-8")
      : undefined;

    // An unchanged file is not rewritten, so nothing watching it sees a change.
    const written = previous !== printed.code;

    if (written) {
      await writeFile(this.out, printed.code);
    }

    return {
      queries: printed.queries,
      errors: [
        ...[...this.modules.values()].flatMap((m) => m.errors),
        ...printed.errors,
      ],
      written,
    };
  }
}

export async function typegen(
  root: string,
  studio: string
): Promise<TypegenResult> {
  const state = new Typegen(root, studio);
  await state.loadSchema();
  state.scan();

  return state.write();
}
